class StateOfNode{
public:    
    int height;
    bool isSubTreeBalanced;

    StateOfNode(int h,bool isSubTreeBalanced){
        this->height = h;
        this->isSubTreeBalanced = isSubTreeBalanced;
    }

    int getHeight(){
        return this->height;
    }

    bool getBalancedSubtreeIndicator(){
        return this->isSubTreeBalanced;
    }
};
class Solution{
public:
    StateOfNode* isBalancedHelper(TreeNode* root){
        if(!root) return new StateOfNode(0,true);
        StateOfNode* left = isBalancedHelper(root->left);
        StateOfNode* right = isBalancedHelper(root->right);
        if(!left->getBalancedSubtreeIndicator()) return left;
        if(!right->getBalancedSubtreeIndicator()) return right;
        if(abs(left->getHeight()-right->getHeight())>1) return new StateOfNode(max(left->getHeight(),right->getHeight())+1,false);
        return new StateOfNode(max(left->getHeight(),right->getHeight())+1,true);

    }
